#![cfg(feature = "archive-provider")]

use nntune_core::{
    archive::v1::{
        digest, Backend, EncryptionIdentity, Id, ObjectIdentity, ObjectRecord, Part, Target,
    },
    archive_source::{ArchiveSource, MAX_RECORD_BYTES},
    media::{self, KeyMode},
    original_source::{OriginalSource, SourceError, MAX_FILE_BYTES, PAYLOAD_FORMAT},
};

fn track(n: u8) -> String {
    format!("00000000-0000-0000-0000-{n:012x}")
}

fn id(value: &str) -> Id {
    Id::new(value).unwrap()
}

// Metadata-only generated bytes, not authenticated media or a provider receipt.
fn object(backend: Backend) -> ObjectRecord {
    let bytes: Vec<u8> = (0..128).map(|n| (n * 31) as u8).collect();
    ObjectRecord {
        identity: ObjectIdentity {
            target: Target {
                tenant: id("tenant-a"),
                backend,
                account: id("routing-config-a"),
                locator: id("allocation-a"),
                generation: id("generation-a"),
                encryption: EncryptionIdentity {
                    format: id(media::FORMAT_LABEL),
                    mode: KeyMode::Random.as_byte(),
                    key_epoch: id("epoch-a"),
                    envelope: id("envelope-a"),
                },
            },
            version: id(if backend == Backend::Nntp {
                "generation-a"
            } else {
                "version-a"
            }),
            bytes: bytes.len() as u64,
            sha256: digest(&bytes),
        },
        operation: id("operation-a"),
        parts: vec![Part {
            offset: 0,
            bytes: bytes.len() as u32,
            sha256: digest(&bytes),
            reference: id("part-a"),
        }],
    }
}

fn encoded(backend: Backend) -> (Vec<u8>, ObjectRecord) {
    let object = object(backend);
    let source = ArchiveSource::from_object(&track(1), "job-a", object.clone()).unwrap();
    (source.encode().unwrap(), object)
}

#[test]
fn both_backend_records_round_trip_without_a_new_write_policy() {
    for backend in [Backend::Nntp, Backend::S3] {
        let (bytes, object) = encoded(backend);
        let source = ArchiveSource::parse(&bytes, &track(1), "job-a", &object.identity).unwrap();
        assert_eq!(source.object(), &object);
        assert_eq!(source.cache_key(), object.identity.cache_key());
        assert_eq!(source.encode().unwrap(), bytes);
    }
}

#[test]
fn stored_identity_not_current_routing_controls_metadata_and_cache_binding() {
    let (bytes, object) = encoded(Backend::S3);
    let original = object.identity;
    for coordinate in 0..11 {
        let mut changed = original.clone();
        match coordinate {
            0 => changed.target.tenant = id("tenant-b"),
            1 => changed.target.backend = Backend::Nntp,
            2 => changed.target.account = id("routing-config-b"),
            3 => changed.target.locator = id("allocation-b"),
            4 => changed.target.generation = id("generation-b"),
            5 => changed.version = id("version-b"),
            6 => changed.target.encryption.format = id("other-format"),
            7 => changed.target.encryption.mode = KeyMode::VaultConvergent.as_byte(),
            8 => changed.target.encryption.key_epoch = id("epoch-b"),
            9 => changed.target.encryption.envelope = id("envelope-b"),
            10 => changed.sha256[0] ^= 1,
            _ => unreachable!(),
        }
        assert_ne!(original.cache_key(), changed.cache_key());
        assert_eq!(
            ArchiveSource::parse(&bytes, &track(1), "job-a", &changed).err(),
            Some(SourceError::Binding)
        );
    }
    let mut changed = original.clone();
    changed.bytes += 1;
    assert_ne!(original.cache_key(), changed.cache_key());
    assert_eq!(
        ArchiveSource::parse(&bytes, &track(1), "job-a", &changed).err(),
        Some(SourceError::Binding)
    );
    for (track_id, job) in [(track(2), "job-a"), (track(1), "job-b")] {
        assert_eq!(
            ArchiveSource::parse(&bytes, &track_id, job, &original).err(),
            Some(SourceError::Binding)
        );
    }
}

#[test]
fn foreign_crypto_and_nonimmutable_versions_are_refused() {
    for backend in [Backend::Nntp, Backend::S3] {
        for field in 0..4 {
            let mut object = object(backend);
            match field {
                0 => object.identity.target.encryption.format = id("foreign-format"),
                1 => object.identity.target.encryption.mode = KeyMode::VaultConvergent.as_byte(),
                2 => object.identity.target.encryption.mode = KeyMode::PublicConvergent.as_byte(),
                3 => object.identity.version = id("null"),
                _ => unreachable!(),
            }
            assert!(ArchiveSource::from_object(&track(1), "job-a", object).is_err());
        }
    }
}

#[test]
fn malformed_manifest_and_ciphertext_geometry_are_refused() {
    for field in 0..6 {
        let mut object = object(Backend::S3);
        match field {
            0 => object.parts[0].offset = 1,
            1 => object.parts[0].bytes -= 1,
            2 => object.parts.clear(),
            3 => object.parts.push(object.parts[0].clone()),
            4 => {
                object.identity.bytes = media::HEADER_SIZE + media::TAG_SIZE - 1;
                object.parts[0].bytes = object.identity.bytes as u32;
            }
            5 => object.identity.bytes = MAX_FILE_BYTES + 1,
            _ => unreachable!(),
        }
        assert!(ArchiveSource::from_object(&track(1), "job-a", object).is_err());
    }
}

#[test]
fn decoder_is_bounded_versioned_and_has_value_free_errors() {
    let (bytes, object) = encoded(Backend::S3);
    for bytes in [Vec::new(), vec![b' '; MAX_RECORD_BYTES + 1]] {
        assert_eq!(
            ArchiveSource::parse(&bytes, &track(1), "job-a", &object.identity).err(),
            Some(SourceError::Bounds)
        );
    }
    let record: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
    for field in 0..5 {
        let mut changed = record.clone();
        match field {
            0 => changed["version"] = 2.into(),
            1 => changed["track_id"] = "private-invalid-track-value".into(),
            2 => changed["source_job_id"] = "private/invalid/job".into(),
            3 => changed["unexpected"] = "private-unknown-field".into(),
            4 => changed["object"]["identity"]["target"]["account"] = "".into(),
            _ => unreachable!(),
        }
        let changed = serde_json::to_vec(&changed).unwrap();
        let error = ArchiveSource::parse(&changed, &track(1), "job-a", &object.identity)
            .err()
            .unwrap();
        assert!(!format!("{error:?}").contains("private"));
    }
}

#[test]
fn archive_metadata_never_reinterprets_legacy_original_source() {
    let (bytes, _) = encoded(Backend::Nntp);
    assert!(OriginalSource::parse(PAYLOAD_FORMAT, &bytes, &track(1), "job-a").is_err());
    // The existing import schema and format remain untouched; no fabricated
    // ciphertext hashes or encryption identity are assigned to imported FLAC.
    assert_eq!(PAYLOAD_FORMAT, 1);
}
